public enum CiCdRuntimeConfigurationState{Unconfigured,Invalid,Configured}
public sealed class CiCdRuntimeOptions{public const string SectionName="Platform:SoftwareFactory:CiCdRuntime";public string Endpoint{get;init;}=string.Empty;public string GatewayProfile{get;init;}=string.Empty;public string OperatorId{get;init;}=string.Empty;public string SignatureAlgorithm{get;init;}=string.Empty;public Dictionary<string,string> TrustedPublicKeysPem{get;init;}=new(StringComparer.Ordinal);public int RequestTimeoutSeconds{get;init;}public int MaximumRequestBytes{get;init;}public int MaximumResponseBytes{get;init;}public CiCdRuntimeConfigurationState ConfigurationState{get{if(new[]{Endpoint,GatewayProfile,OperatorId,SignatureAlgorithm}.All(string.IsNullOrWhiteSpace)&&TrustedPublicKeysPem.Count==0&&RequestTimeoutSeconds==0&&MaximumRequestBytes==0&&MaximumResponseBytes==0)return CiCdRuntimeConfigurationState.Unconfigured;if(!Uri.TryCreate(Endpoint,UriKind.Absolute,out var u)||u.Scheme!=Uri.UriSchemeHttps||!string.IsNullOrEmpty(u.UserInfo)||!string.IsNullOrEmpty(u.Query)||!string.IsNullOrEmpty(u.Fragment)||string.IsNullOrWhiteSpace(GatewayProfile)||string.IsNullOrWhiteSpace(OperatorId)||SignatureAlgorithm is not("RS256" or "ES256")||TrustedPublicKeysPem.Count==0||RequestTimeoutSeconds<=0||MaximumRequestBytes<=0||MaximumResponseBytes<=0)return CiCdRuntimeConfigurationState.Invalid;return CiCdRuntimeConfigurationState.Configured;}}public bool IsOperationallyConfigured=>ConfigurationState==CiCdRuntimeConfigurationState.Configured;}
public sealed record CiCdRuntimeReadiness(CiCdRuntimeConfigurationState State);

