{public async Task<CiCdPolicyDecision> EvaluateAsync(CiCdPolicyInput i,CancellationToken ct){var v=await bundleVerifier.VerifyAsync(new(i.PolicyBundle.BundleId,i.PolicyBundle.Version,i.PolicyBundle.Sha256Digest,i.PolicyBundle.SignatureReference,i.PolicyBundle.Environment,i.PolicyBundle.ActivatedAt),ct);var a=new Dictionary<string,string>(StringComparer.Ordinal){["executionId"]=i.ExecutionId.ToString("D"),["gitOperationId"]=i.GitOperationId.ToString("D"),["deliveryRunId"]=i.DeliveryRunId.ToString("D"),["repositoryId"]=i.RepositoryId,["commitId"]=i.CommitId,["treeSha256Digest"]=i.TreeSha256Digest,["changeSetSha256Digest"]=i.ChangeSetSha256Digest,["workflowDefinitionId"]=i.WorkflowDefinitionId,["workflowDefinitionVersion"]=i.WorkflowDefinitionVersion,["workflowSha256Digest"]=i.WorkflowSha256Digest,["workflowSignatureReference"]=i.WorkflowSignatureReference,["pipelineProfile"]=i.PipelineProfile,["runnerPoolId"]=i.RunnerPoolId,["requiredStageIds"]=string.Join(',',i.RequiredStageIds),["requiredControlIds"]=string.Join(',',i.RequiredControlIds.Order(StringComparer.Ordinal))}.ToImmutableSortedDictionary(StringComparer.Ordinal);var ev=i.EvidenceReferences.Append(v.VerificationEvidenceReference).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToImmutableArray();var d=await client.EvaluateAsync(new(i.DecisionRequestId,"internal-service.cicd.execute",i.CommitId,i.TenantId,i.SubjectId,i.Purpose,i.MaximumClassification.ToString(),i.Environment,v,a,ev,v.VerifiedAt>i.EvaluatedAt?v.VerifiedAt:i.EvaluatedAt),ct);if(d.Outcome==OpaDecisionOutcome.Deny){if(d.Scope is not null)throw new UnauthorizedAccessException("Denied CI/CD decision returned scope.");return Make(i,v,d,GovernedIntentPolicyOutcome.Deny,i.MaximumClassification,i.RequiredStageIds,i.RequiredControlIds,false,false,false);}var e=d.Scope??throw new UnauthorizedAccessException("CI/CD scope missing.");var s=e.CiCd??throw new UnauthorizedAccessException("CI/CD action scope missing.");if(e.Git is not null||e.HumanReview is not null||e.Tests is not null||e.Sandbox is not null||e.SecurityValidation is not null||e.StaticValidation is not null||e.CodeGeneration is not null||e.AiPlanning is not null||e.ApprovedPackages is not null||e.ExistingArchitecture is not null||e.ExistingSystems is not null)throw new UnauthorizedAccessException("CI/CD decision mixed scopes.");if(!Enum.TryParse<DataClassification>(s.MaximumClassification,true,out var c)||s.RepositoryId!=i.RepositoryId||!StringComparer.OrdinalIgnoreCase.Equals(s.CommitId,i.CommitId)||!StringComparer.OrdinalIgnoreCase.Equals(s.TreeSha256Digest,i.TreeSha256Digest)||!StringComparer.OrdinalIgnoreCase.Equals(s.ChangeSetSha256Digest,i.ChangeSetSha256Digest)||s.WorkflowDefinitionId!=i.WorkflowDefinitionId||s.WorkflowDefinitionVersion!=i.WorkflowDefinitionVersion||!StringComparer.OrdinalIgnoreCase.Equals(s.WorkflowSha256Digest,i.WorkflowSha256Digest)||s.PipelineProfile!=i.PipelineProfile||s.RunnerPoolId!=i.RunnerPoolId||!s.AllowedStageIds.SequenceEqual(i.RequiredStageIds)||!s.AllowedControlIds.ToImmutableHashSet(StringComparer.Ordinal).SetEquals(i.RequiredControlIds)||s.SourceMutationAllowed||s.ArtifactPublicationAllowed||s.DeploymentAllowed||s.RequiredRoles.IsDefaultOrEmpty||s.OutputKind!="cicd-result")throw new UnauthorizedAccessException("CI/CD scope mismatch.");return Make(i,v,d,GovernedIntentPolicyOutcome.Permit,c,s.AllowedStageIds,s.AllowedControlIds.ToImmutableHashSet(StringComparer.Ordinal),s.SourceMutationAllowed,s.ArtifactPublicationAllowed,s.DeploymentAllowed);}
private static CiCdPolicyDecision Make(CiCdPolicyInput i,PolicyBundleVerification v,SovereignPolicyEvaluationDecision d,GovernedIntentPolicyOutcome o,DataClassification c,ImmutableArray<string> stages,ImmutableHashSet<string> controls,bool source,bool artifact,bool deployment)=>new(i.DecisionRequestId,i.ExecutionId,i.GitOperationId,i.DeliveryRunId,i.TenantId,i.Environment,i.RepositoryId,i.CommitId,i.TreeSha256Digest,i.ChangeSetSha256Digest,i.WorkflowDefinitionId,i.WorkflowDefinitionVersion,i.WorkflowSha256Digest,i.PipelineProfile,i.RunnerPoolId,stages,controls,source,artifact,deployment,v.BundleId,v.Version,v.Sha256Digest,true,v.VerificationEvidenceReference,o,c,d.Reasons,d.EvidenceReferences,d.DecidedAt);}

public sealed class SovereignHttpCiCdGateway(IHttpClientFactory factory,IOptions<CiCdRuntimeOptions> configured):ICiCdWorkflowValidator,IInstitutionalCiCdGateway
{private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);public Task<CiCdWorkflowValidationDecision> ValidateAsync(CiCdWorkflowValidationRequest r,CancellationToken ct)=>Invoke<CiCdWorkflowValidationDecision>("validate",r,ct);public Task<InstitutionalCiCdExecutionResult> ExecuteAsync(InstitutionalCiCdExecutionRequest r,CancellationToken ct)=>Invoke<InstitutionalCiCdExecutionResult>("execute",r,ct);private async Task<T> Invoke<T>(string action,object request,CancellationToken ct){var o=configured.Value;if(!o.IsOperationallyConfigured)throw new CiCdDependencyUnavailableException("CI/CD gateway not configured.");var id=Guid.NewGuid();var input=Hash($"{id:D}|{action}|{o.OperatorId}|{o.GatewayProfile}|{Hash(JsonSerializer.Serialize(request,Json))}");var bytes=JsonSerializer.SerializeToUtf8Bytes(new Request(id,action,o.OperatorId,o.GatewayProfile,input,request),Json);if(bytes.Length>o.MaximumRequestBytes)throw new UnauthorizedAccessException("CI/CD request exceeds bound.");using var msg=new HttpRequestMessage(HttpMethod.Post,o.Endpoint){Content=new ByteArrayContent(bytes)};msg.Headers.Add("X-Governed-Operation",action);msg.Content.Headers.ContentType=new("application/json");using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(o.RequestTimeoutSeconds));try{using var response=await factory.CreateClient("sovereign-institutional-cicd").SendAsync(msg,HttpCompletionOption.ResponseHeadersRead,timeout.Token);if(!response.IsSuccessStatusCode)throw new CiCdDependencyUnavailableException("CI/CD gateway rejected request.");var body=await SovereignAiHttp.ReadBoundedAsync(response.Content,o.MaximumResponseBytes,timeout.Token);var r=JsonSerializer.Deserialize<Response<T>>(body,Json)??throw new InvalidOperationException("Empty CI/CD response.");if(r.InvocationId!=id||r.Action!=action||r.OperatorId!=o.OperatorId||r.GatewayProfile!=o.GatewayProfile||!StringComparer.OrdinalIgnoreCase.Equals(r.InputSha256Digest,input)||r.Payload is null||string.IsNullOrWhiteSpace(r.EvidenceReference)||r.CompletedAt==default)throw new UnauthorizedAccessException("CI/CD response binding invalid.");var signed=$"{r.InvocationId:D}|{r.Action}|{r.OperatorId}|{r.GatewayProfile}|{r.InputSha256Digest}|{Hash(JsonSerializer.Serialize(r.Payload,Json))}|{r.EvidenceReference}|{r.CompletedAt:O}|{r.Signature.Algorithm}|{r.Signature.KeyId}|{r.Signature.CertificateChainReference}|{r.Signature.SignedAt:O}";if(!AiPlanningSignatureVerifier.Verify(o.SignatureAlgorithm,o.TrustedPublicKeysPem,r.Signature,SHA256.HashData(Encoding.UTF8.GetBytes(signed))))throw new UnauthorizedAccessException("CI/CD response signature invalid.");return r.Payload;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new CiCdDependencyUnavailableException("CI/CD gateway timed out.");}catch(HttpRequestException){throw new CiCdDependencyUnavailableException("CI/CD gateway unavailable.");}}private static string Hash(string x)=>Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(x)));private sealed record Request(Guid InvocationId,string Action,string OperatorId,string GatewayProfile,string InputSha256Digest,object Payload);private sealed record Response<T>(Guid InvocationId,string Action,string OperatorId,string GatewayProfile,string InputSha256Digest,T Payload,string EvidenceReference,DateTimeOffset CompletedAt,SignatureEnvelope Signature);}

public sealed class DeterministicCiCdResultAuthorizer:ICiCdResultAuthorizer{public Task<CiCdResultAuthorizationDecision> AuthorizeAsync(CiCdResultAuthorizationRequest r,CancellationToken ct){ct.ThrowIfCancellationRequested();if(!r.Result.CiCdTriggered||r.Result.SourceMutationOccurred||r.Result.ArtifactPublished||r.Result.DeploymentOccurred||r.Result.ProductionEffectOccurred)throw new UnauthorizedAccessException("Unsafe CI/CD result.");var h=Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes($"{r.AuthorizationRequestId:D}|{r.Result.OutputManifest.ManifestSha256Digest}|{r.SubjectId}")));return Task.FromResult(new CiCdResultAuthorizationDecision(r.AuthorizationRequestId,r.ExecutionId,r.TenantId,r.Result.OutputManifest.ManifestSha256Digest,true,"cicd-result-authorized",r.EvidenceReferences.Append($"evidence://cicd/result-authorization/{r.AuthorizationRequestId:D}/sha256/{h}").ToImmutableArray(),r.RequestedAt));}}
